#!/usr/bin/env bash
# shellcheck source-path=SCRIPTDIR
# add-sla-tiers.sh — Create or update SLA tiers from the env-settings tier files.
#
# GENERATED by tests/parity/extract_inline_bash.py — do not hand-edit (change the Azure source or
# the extractor, then run it with --write). Extracted from the Azure DevOps inline step:
#   source : platforms/azure-devops/mulesoft-pipeline-templates/pipelines/templates/tasks/add-sla-tiers.yml
#   step   : "Add SLA Tiers to API Manager Instance" (Bash@3 inline)
# The body is that step verbatim, except: ##vso commands -> ci-shim calls, Azure predefined
# variables -> ci-shim normalizers, and $(...) / ${{ parameters.* }} macros -> the MDF_* inputs below.
#
# Inputs (environment):
#   MDF_API_ID          <- ${{ parameters.apiId }}  [required]
#   MDF_BEARER_TOKEN    <- ${{ parameters.bearerToken }}  [required]
#   MDF_BG_ID           <- ${{ parameters.bgId }}  [default: $(BG_ID)]
#   MDF_ENV_ID          <- ${{ parameters.envId }}  [default: $(ENV_ID)]
#   MDF_SLA_TIERS_PATH  <- ${{ parameters.slaTiersPath }}  [required]

# shellcheck source=lib/ci-shim.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/ci-shim.sh"

: "${MDF_API_ID?MDF_API_ID is required (Azure parameter apiId)}"
: "${MDF_BEARER_TOKEN?MDF_BEARER_TOKEN is required (Azure parameter bearerToken)}"
: "${MDF_BG_ID=}"
: "${MDF_ENV_ID=}"
: "${MDF_SLA_TIERS_PATH?MDF_SLA_TIERS_PATH is required (Azure parameter slaTiersPath)}"

# >>> extracted body
BG_ID="${MDF_BG_ID}"
ENV_ID="${MDF_ENV_ID}"
API_ID="${MDF_API_ID}"
TIER_PATH="${MDF_SLA_TIERS_PATH}"

echo "[DEBUG] ============================================"
echo "[DEBUG] ADD SLA TIERS"
echo "[DEBUG] ============================================"
echo "[DEBUG] Parameters:"
echo "[DEBUG]   bgId=$BG_ID"
echo "[DEBUG]   envId=$ENV_ID"
echo "[DEBUG]   apiId=$API_ID"
echo "[DEBUG]   slaTiersPath=$TIER_PATH"
echo "[DEBUG] ============================================"

if [ ! -d "$TIER_PATH" ]; then
  echo "[DEBUG] SLA Tiers folder NOT FOUND: $TIER_PATH"
  ci_log_warning "SLA Tiers folder not found: $TIER_PATH. Skipping."
  exit 0
fi

TIER_FILES=$(find "$TIER_PATH" -maxdepth 1 -type f -name "*.json" | sort)

if [ -z "$TIER_FILES" ]; then
  echo "[DEBUG] No *.json files in $TIER_PATH"
  echo "No SLA tier files found. Skipping."
  exit 0
fi

echo "Found SLA tier files: $(echo "$TIER_FILES" | xargs -n 1 basename)"

# Fetch existing tiers on the API instance
echo "[DEBUG] Fetching existing SLA tiers for API $API_ID..."
EXISTING_TIERS=$(curl -s --request GET \
  --url "https://anypoint.mulesoft.com/apimanager/api/v1/organizations/${BG_ID}/environments/${ENV_ID}/apis/${API_ID}/tiers" \
  --header "Authorization: Bearer ${MDF_BEARER_TOKEN}")
echo "[DEBUG] Existing tiers count: $(echo "$EXISTING_TIERS" | jq '.total // (. | length)' 2>/dev/null || echo 'parse-error')"
echo "[DEBUG] Existing tier names: $(echo "$EXISTING_TIERS" | jq -r '.tiers[]?.name // empty' 2>/dev/null || echo 'none')"

for TIER_FILE in $TIER_FILES; do
  CONTENT=$(cat "$TIER_FILE")
  TIER_NAME=$(echo "$CONTENT" | jq -r '.tierName')
  TIER_PAYLOAD=$(echo "$CONTENT" | jq -c '.payload')

  echo "[DEBUG] Processing tier file: $(basename "$TIER_FILE") — tierName=$TIER_NAME"
  echo "[DEBUG] Tier payload: $TIER_PAYLOAD"

  # Check if tier already exists by name
  EXISTING_TIER_ID=$(echo "$EXISTING_TIERS" | jq -r --arg name "$TIER_NAME" '.tiers[]? | select(.name == $name) | .id // empty')
  echo "[DEBUG] Existing tier ID for '$TIER_NAME': ${EXISTING_TIER_ID:-not found}"

  if [[ -n "$EXISTING_TIER_ID" && "$EXISTING_TIER_ID" != "null" ]]; then
    # Tier exists — update it via PUT
    echo "Updating SLA Tier: $TIER_NAME (ID: $EXISTING_TIER_ID)"

    update_response=$(curl -i -s --request PUT \
      --url "https://anypoint.mulesoft.com/apimanager/api/v1/organizations/${BG_ID}/environments/${ENV_ID}/apis/${API_ID}/tiers/${EXISTING_TIER_ID}" \
      --header "Content-Type: application/json" \
      --header "Authorization: Bearer ${MDF_BEARER_TOKEN}" \
      --data "$TIER_PAYLOAD")

    UPDATE_STATUS=$(echo "$update_response" | head -n 1 | awk '{print $2}')
    UPDATE_BODY=$(echo "$update_response" | sed -n '/^\r\{0,1\}$/,$p' | tail -n +2)
    echo "[DEBUG] Update tier response status: $UPDATE_STATUS"

    if [[ "$UPDATE_STATUS" == "200" ]]; then
      echo "  SLA Tier '$TIER_NAME' updated successfully."
    else
      ci_log_warning "Failed to update SLA Tier '$TIER_NAME'. Status: $UPDATE_STATUS"
      echo "[DEBUG] Update response: $UPDATE_BODY"
    fi
  else
    # Tier does not exist — create it via POST
    echo "Creating SLA Tier: $TIER_NAME"

    create_response=$(curl -i -s --location \
      "https://anypoint.mulesoft.com/apimanager/api/v1/organizations/${BG_ID}/environments/${ENV_ID}/apis/${API_ID}/tiers" \
      --header "Content-Type: application/json" \
      --header "Authorization: Bearer ${MDF_BEARER_TOKEN}" \
      --data "$TIER_PAYLOAD")

    HTTP_STATUS=$(echo "$create_response" | head -n 1 | awk '{print $2}')
    BODY=$(echo "$create_response" | sed -n '/^\r\{0,1\}$/,$p' | tail -n +2)

    if [[ "$HTTP_STATUS" == "201" ]]; then
      echo "  SLA Tier '$TIER_NAME' created successfully."
    elif [[ "$HTTP_STATUS" == "409" ]]; then
      echo "  SLA Tier '$TIER_NAME' already exists (concurrent creation)."
    else
      ci_log_error "Failed to create SLA Tier '$TIER_NAME'. Status: $HTTP_STATUS"
      echo "Response: $BODY"
      exit 1
    fi
  fi
done

echo "SLA Tier management completed."
echo "[DEBUG] ADD SLA TIERS COMPLETE"
# <<< extracted body
